219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	
224	    /**
225	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
226	     * the canonical form each stored value must take: the address is trimmed,
227	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
228	     * telephone is converted to E.164, any email is lower-cased and a missing
229	     * registration date defaults to today. Field-level rejections are reported here
230	     * rather than inline in {@link #addOwner}, and normalisation runs before any
231	     * household comparison so those comparisons see the canonical values.
232	     *
233	     * @param owner the freshly-mapped owner to normalise
234	     * @return {@code true} if the fields are valid, or {@code false} if the address
235	     *         is blank after normalisation or the telephone cannot form a valid
236	     *         E.164 number, in which case the request must be rejected with
237	     *         {@code 400 Bad Request}
238	     */
239	    private boolean normalizeNewOwner(Owner owner) {
240	        String address = Owner.normalizeAddress(owner.getAddress());
241	        if (address.isEmpty()) {
242	            return false;
243	        }
244	        owner.setAddress(address);
245	        String telephone = toE164(owner.getTelephone());
246	        if (telephone == null) {
247	            return false;
248	        }
249	        owner.setTelephone(telephone);
250	        if (owner.getEmail() != null) {
251	            owner.setEmail(owner.getEmail().toLowerCase());
252	        }
253	        if (owner.getRegistrationDate() == null) {
254	            owner.setRegistrationDate(LocalDate.now());
255	        }
256	        return true;
257	    }
258	
259	    /**
260	     * Find an existing owner that belongs to the same household as the given owner,
261	     * i.e. shares the same last name and address (compared case-insensitively with
262	     * runs of whitespace collapsed to a single space).
263	     *
264	     * @param owner the candidate owner being created
265	     * @return the matching existing owner, or empty if none exists
266	     */
267	    private Optional<Owner> findHouseholdMember(Owner owner) {
268	        return this.clinicService.findAllOwners().stream()
269	            .filter(existing -> existing.sameHouseholdAs(owner))
270	            .findFirst();
271	    }
272	
273	    /**
274	     * Assign the joining owner and an existing household member the same stable
275	     * household identifier. The identifier is derived deterministically from the
276	     * shared household key (last name + address, normalised), so every owner in a
277	     * household resolves to the same value; the existing member is updated when it
278	     * does not already carry it.
279	     *
280	     * @param owner    the owner being created
281	     * @param existing an existing owner in the same household
282	     */
283	    private void joinHousehold(Owner owner, Owner existing) {
284	        String householdId = UUID
285	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
286	        owner.setHouseholdId(householdId);
287	        if (!householdId.equals(existing.getHouseholdId())) {
288	            existing.setHouseholdId(householdId);
289	            this.clinicService.saveOwner(existing);
290	        }
291	    }
292	
293	    /**
294	     * Build the next customer code, formatted {@code <LAST3>-<NNNN>}: LAST3 is the
295	     * upper-cased first three letters of the given last name and NNNN is a global
296	     * 4-digit zero-padded sequence equal to one more than the current number of
297	     * owners (e.g. {@code SMI-0007}).
298	     *
299	     * @param lastName the owner's last name
300	     * @return the assigned customer code
301	     */
302	    private String nextCustomerCode(String lastName) {
303	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
304	        long sequence = this.clinicService.findAllOwners().size() + 1L;
305	        return String.format("%s-%04d", last3, sequence);
306	    }
307	
308	    /**
309	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
310	     * code when present, otherwise assume country code '+61' and drop a single
311	     * leading '0' from the national digits. Spaces, dashes and brackets are
312	     * stripped. The result must contain 8 to 15 digits after the '+'.
313	     *
314	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
315	     *         input cannot form a valid E.164 number.
316	     */
317	    private static String toE164(String raw) {
318	        if (raw == null) {
319	            return null;
320	        }
321	        String cleaned = raw.replaceAll("[\\s()-]", "");
322	        String digits;
323	        if (cleaned.startsWith("+")) {
324	            digits = cleaned.substring(1);
325	        } else {
326	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
327	            digits = "61" + national;
328	        }
329	        if (!digits.matches("\\d{8,15}")) {
330	            return null;
331	        }
332	        return "+" + digits;
333	    }
334	}
